/* ERASABLE_ASSIGNMENTS.agc (LM pp. 90-152, CM pp. 37-130): the name and the
 * place of every word of erasable memory. The file makes no word of the
 * rope. It tells the assembler where each register, counter, channel and
 * variable is, and its comments say what each is: how many words, who
 * uses it, its scaling. The CM's file assigns the flags as well (CM pp.
 * 42-67; the LM's are in flagword_assignments.c).
 *
 * ERASABLE_ASSIGNMENTS is the file line by line (struct erasable_line in
 * assembly.h): a card with its name, its operand as the listing writes it
 * and the comment beside it, or a line of comment alone. Blank lines are
 * left out, and the listing's pages are in the comments here. To each name
 * the table adds what this file of the listing does not print, the name's
 * value in the assembled program, from the assembler's symbol table:
 * IN_ERASABLE(a) for a word of erasable memory, NUMBER(n) for a number,
 * IN_FIXED(a) for a word of fixed memory.
 *
 * The cards (the listing's first pages, the first lines below, say how the
 * program uses them):
 *   SETLOC  goes to an address of erasable memory;
 *   ERASE   takes the next word from there and gives it the card's name:
 *           one word, or with an operand +n the n words after it too, or
 *           with an operand a - b the words from a to b;
 *   EQUALS  gives a name the place of its operand, a number or another
 *           name and a count of words after it; with no operand, the next
 *           word an ERASE would take;
 *   =       does what EQUALS does. The listing writes it where two names
 *           are one datum.
 * tests/assembly_cases.py follows the SETLOC and ERASE cards through the
 * table and must find every word they name where the table says it is.
 *
 * The CM's flags. A flag's name is a number, the flag's number, and flag n
 * is bit 15 - n % 15 of flagword n / 15 (the flagwords are the words from
 * STATE on). The name of a flag's bit is the address of the constant with
 * only that bit, BIT15 to BIT1, in fixed memory. In the lines that assign
 * the flags the comments stand in two columns, what the flag means set and
 * what it means reset, and the table keeps them apart, line by line, as
 * set and reset. Before those lines is the listing's sorted list of the
 * flags (name, number, bit and flagword), which is not everywhere in step
 * with the assignments: it has DMENFLAG for DMENFLG; ENG1FLAG at 018D,
 * which is NODOP01; IDLEFLAG at 113D and V67FLAG at 136D, numbers the
 * assignments give no name; PRFTRKAT at 060D, which is 080D; and RPQFLAG,
 * 120D, in flagword 6, which is bit 15 of flagword 8. */
#include <stddef.h>
#include "assembly.h"

/* A line of the file, by what is on it: a comment alone; a card (its name,
 * the card, its operand, the name's value), alone or with the comment
 * beside it; and in the CM's flag lines a comment in the SET and RESET
 * columns, alone or beside a card. */
/* clang-format off */
#define REMARK(remark)                   {NULL, NULL, NULL, NO_VALUE, remark, NULL, NULL}
#define CARD(name, card, operand, value) {name, card, operand, value, NULL, NULL, NULL}
#define CARD_AND_REMARK(name, card, operand, value, remark) \
    {name, card, operand, value, remark, NULL, NULL}
#define SET_RESET(set, reset)            {NULL, NULL, NULL, NO_VALUE, NULL, set, reset}
#define CARD_SET_RESET(name, card, operand, value, set, reset) \
    {name, card, operand, value, NULL, set, reset}
/* clang-format on */

